interface.definition:
a!localVariables(
  local!sumarizadas: index(ri!sumarizadas, "body", {}),
  local!vivienda: index(ri!vivienda, "body", {}),
  local!totales: index(ri!totales, "body", {}),
  local!docId_int,
  local!show: false,
  local!idLiberacion: tointeger(
    index(
      local!sumarizadas,
      "contributionRelease",
      1,
      "id",
      0
    )
  ),
  local!totOrdElement: wherecontains(
    268,
    tointeger(
      index(
        local!totales,
        "contributionRelease",
        "id",
        {}
      )
    )
  ),
  local!totAclElement: wherecontains(
    269,
    tointeger(
      index(
        local!totales,
        "contributionRelease",
        "id",
        {}
      )
    )
  ),
  local!totTotElement: wherecontains(
    0,
    tointeger(
      index(
        local!totales,
        "contributionRelease",
        "id",
        {}
      )
    )
  ),
  local!preSief: index(
    #"_a-0000ef47-4270-8000-9bc5-011c48011c48_544300"(
      folio: ri!archivo.folio,
      fileId: ri!archivo.identificador,
      depositTypes: "268,269"
    ),
    "result",
    "body",
    {}
  ),
  local!elementOrdExist: wherecontains(
    268,
    tointeger(index(local!preSief, "id", {}))
  ),
  local!elementAclExist: wherecontains(
    269,
    tointeger(index(local!preSief, "id", {}))
  ),
  local!ordAcl: a!localVariables(
    local!idAclaracion: wherecontains(
      269,
      tointeger(
        index(
          local!sumarizadas,
          "contributionRelease",
          "id",
          {}
        )
      )
    ),
    local!idOrdinarias: wherecontains(
      268,
      tointeger(
        index(
          local!sumarizadas,
          "contributionRelease",
          "id",
          {}
        )
      )
    ),
    a!map(
      ordinarias: a!flatten(
        index(
          local!sumarizadas,
          "contributionRelease",
          local!idOrdinarias,
          {}
        )
      ),
      aclaraciones: a!flatten(
        index(
          local!sumarizadas,
          "contributionRelease",
          local!idAclaracion,
          {}
        )
      )
    )
  ),
  local!sieforesSum: a!localVariables(
    local!siefores: #"db37850c-4c51-4ee3-9a12-95f3860e063c"(catalogTypeId_int: 18).result.body,
    local!amount: index(
      local!sumarizadas,
      "contributionRelease",
      "summarizedCipher",
      "amountBySiefore",
      {}
    ),
    local!iteracionesAmount: a!flatten(
      #"SYSTEM_SYSRULES_forEach"(
        items: local!amount,
        expression: index(fv!item, "siefore", "id", {})
      )
    ),
    local!identificacion: union(
      local!iteracionesAmount,
      local!iteracionesAmount
    ),
    #"SYSTEM_SYSRULES_forEach"(
      items: local!siefores,
      expression: if(
        and(
          a!isNotNullOrEmpty(local!identificacion),
          contains(
            local!identificacion,
            tointeger(fv!item.CatCatalogId)
          )
        ),
        {
          desc: fv!item.value,
          id: fv!item.CatCatalogId
        },
        {}
      )
    ),

  ),
  local!showColumn: true,
  local!showPopWarning: false,
  local!existBitacora: if(
    a!isNullOrEmpty(ri!request),
    1,
    #"SYSTEM_SYSRULES_queryRecordType_v2"(
      recordType: #"urn:appian:record-type:v1:2e875f37-a45c-4931-b48c-bcbd5e117aba",
      filters: #"SYSTEM_SYSRULES_queryFilter"(
        field: #"urn:appian:record-field:v1:2e875f37-a45c-4931-b48c-bcbd5e117aba/c6c64a7e-8d1d-491d-9ed8-b477f1266091",
        operator: "=",
        value: tointeger(ri!request.idInstancia)
      ),
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1)
    ).data[#"urn:appian:record-field:v1:2e875f37-a45c-4931-b48c-bcbd5e117aba/c6c64a7e-8d1d-491d-9ed8-b477f1266091"]
  ),
  local!AceptBitacora: if(
    a!isNullOrEmpty(local!existBitacora),
    true,
    false
  ),
  local!vistaRechazoFolio: false,
  local!vistaContinuar: false,
  local!intentoDescarga: false,
  local!mensajeRespuesta: "",
  local!mapeadoAjuste: if(
    or(
      index(ri!archivo, "subproceso", "id", 0) = 122, 
      index(ri!archivo, "subproceso", "id", 0) = 120
    ), 
    true, 
    false
  ),
  local!cuentas: index(
    ri!sumarizadas,
    "body",
    "contributionRelease",
    /*1,*/
    /*"summarizedCipher",*/
    {}
  ),
  /*Agregado para  descarga asincrona bloque*/
  local!consultaDoc:a!refreshVariable(
    value: if(
      and(local!intentoDescarga,local!mensajeRespuesta="Incompleto"),
      #"f74c3fea-f7cf-4af7-8537-3a66751225ec"(
        folio: index(ri!archivo, "description", "folio", null),
        /*IMPORTANTE CAMBIAR A LA OPCION DE LA DESCARAGA*/
        option: 10,
        idInstancia: index(ri!request, "processInstanceId", null),
      ),
      null
    ),
    refreshInterval: 0.5
  ),
  /*Agregado para  descarga asincrona bloque*/
  {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
