                        #"SYSTEM_SYSRULES_columnsLayout"(
                          columns: {
                            #"SYSTEM_SYSRULES_columnLayout"(),
                            #"SYSTEM_SYSRULES_columnLayout"(
                              contents: {
                                #"SYSTEM_SYSRULES_boxLayout"(
                                  label: "Rechazar folio",
                                  contents: {
                                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                                      labelPosition: "COLLAPSED",
                                      value: {
                                        "¿Estás seguro de que deseas ",
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(text: { "rechazar" }, style: { "STRONG" }),
                                        " este folio?"
                                      }
                                    ),
                                    #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                                      buttons: {
                                        #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                          label: "Aceptar",
                                          saveInto: {
                                            a!save(ri!action_int, 2),
                                            a!save(local!vistaRechazoFolio, false),

                                          },
                                          submit: true,
                                          style: "SOLID",
                                          color: #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_93774"
                                        ),
                                        #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                          label: "Cancelar",
                                          saveInto: { a!save(local!vistaRechazoFolio, false) },
