                                      value: {
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                                          text: "Nombre:  ",
                                          style: "STRONG",
                                          color: "#000000"
                                        ),
                                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                                          text: ri!archivo.nombreArchSinExtension,
                                          color: "#000000"
                                        )
                                      },
                                      align: "LEFT"
