                                        style: "STRONG",
                                        color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375"
                                      ),
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: if(a!isNotNullOrEmpty(index(ri!archivo, "fechaRecepcion", null)),
                                        text(
                                          gmt(ri!archivo.fechaRecepcion),
                                          "dd/MM/yyyy"
                                        ),
                                        ""
