                                    #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "", align: "CENTER"),
                                    #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "", align: "CENTER")
                                  },
                                  rows: {
                                    #"SYSTEM_SYSRULES_gridRowLayout"(
                                      contents: {
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(
