                                            color: #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_232375"
                                          )
                                        ),
                                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                                          align: "CENTER",
                                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                            text: index(
