                      contents: {
                        a!localVariables(
                          local!selectedTab: 1,
                          {
                            #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                              buttons: {
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Ordinarias",
                                  saveInto: if(
