                                  size: "SMALL",
                                  width: "MINIMIZE",
                                  style: if(local!selectedTab = 2, "SOLID", "SOLID"),
                                  color: if(
                                    local!selectedTab = 2,
                                    #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",
                                    #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_8114"
                                  )
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
                                  label: "Vivienda",
                                  saveInto: if(
                                    local!selectedTab = 3,
                                    {},
                                    a!save(local!selectedTab, 3)
                                  ),
                                  size: "SMALL",
                                  width: "MINIMIZE",
                                  style: if(local!selectedTab = 3, "SOLID", "SOLID"),
                                  color: if(
                                    local!selectedTab = 3,
                                    #"_a-0000ecfb-6f0d-8000-9baa-011c48011c48_236350",
                                    #"_a-0000ec44-2ff4-8000-9ba5-011c48011c48_8114"
                                  )
                                ),
                                #"SYSTEM_SYSRULES_buttonWidget_v1"(
